"""Database-backed checks for the navigation generated by ``bench migrate``."""

import json
from pathlib import Path
from unittest.mock import MagicMock, patch

import frappe
from frappe.desk import desk_page
from frappe.tests import UnitTestCase


class TestWorkspaceProvisioning(UnitTestCase):
    DASHBOARDS = {
        "RundiNova Executive Dashboard",
        "RundiNova Finance Dashboard",
        "RundiNova People Dashboard",
        "RundiNova Delivery Dashboard",
        "RundiNova Ecosystem Dashboard",
    }

    def test_operations_home_contains_dashboards_and_daily_work(self):
        workspace = frappe.get_doc("Workspace", "RundiNova Tech")
        self.assertFalse(workspace.is_hidden)
        self.assertFalse(
            workspace.module,
            "Site-managed public workspaces must not be treated as orphanable app fixtures.",
        )

        shortcuts = {(row.type, row.link_to) for row in workspace.shortcuts}
        dashboard_links = {target for kind, target in shortcuts if kind == "Dashboard"}
        self.assertEqual(dashboard_links, self.DASHBOARDS)

        doctype_links = {target for kind, target in shortcuts if kind == "DocType"}
        self.assertTrue(
            {"Project", "Task", "RundiNova Food Budget", "RundiNova Food Expense"}
            <= doctype_links
        )
        self.assertTrue(
            {"RundiNova Cash Account", "RundiNova Cash Movement", "RundiNova Expense"}
            <= doctype_links
        )
        self.assertTrue(
            {
                "RundiNova Growth Opportunity",
                "RundiNova Partnership",
                "RundiNova Community Impact",
            }
            <= doctype_links
        )
        self.assertIn(
            "/crm", {row.url for row in workspace.shortcuts if row.type == "URL"}
        )
        self.assertIn(("URL", None), shortcuts)
        self.assertIn(
            "/desk/rundinova-setup",
            {row.url for row in workspace.shortcuts if row.type == "URL"},
        )

        blocks = json.loads(workspace.content or "[]")
        visible_shortcuts = {
            block.get("data", {}).get("shortcut_name")
            for block in blocks
            if block.get("type") == "shortcut"
        }
        dashboard_labels = {
            row.label for row in workspace.shortcuts if row.type == "Dashboard"
        }
        self.assertTrue(dashboard_labels <= visible_shortcuts)

    def test_sidebar_exposes_dashboards_finance_projects_and_tasks(self):
        sidebar = frappe.get_doc("Workspace Sidebar", "RundiNova Tech")
        links = {
            (row.link_type, row.link_to) for row in sidebar.items if row.type == "Link"
        }
        self.assertTrue({("Dashboard", name) for name in self.DASHBOARDS} <= links)
        self.assertTrue(
            {
                ("DocType", "Project"),
                ("DocType", "Task"),
                ("DocType", "RundiNova Food Budget"),
                ("DocType", "RundiNova Food Expense"),
                ("DocType", "RundiNova Cash Movement"),
            }
            <= links
        )
        self.assertIn(
            "/desk/rundinova-setup",
            {
                row.url
                for row in sidebar.items
                if row.type == "Link" and row.link_type == "URL"
            },
        )

