    def test_every_rundinova_role_uses_one_primary_workspace(self):
        workspace = frappe.get_doc("Workspace", "RundiNova Tech")
        roles = {row.role for row in workspace.roles}
        self.assertIn("RundiNova Team Member", roles)
        self.assertTrue(frappe.get_value("Workspace", "RundiNova Team", "is_hidden"))
        if frappe.db.exists("Desktop Icon", "RundiNova Setup"):
            self.assertTrue(
                frappe.get_value("Desktop Icon", "RundiNova Setup", "hidden")
            )
        self.assertFalse(frappe.db.exists("Workspace", "RundiNova Setup"))

    def test_launcher_destinations_have_route_safe_titles_and_distinct_labels(self):
        self.assertEqual(
            frappe.get_value("Workspace", "RundiNova Team", "title"), "RundiNova Team"
        )
        for label, workspace in (("RundiNova Team", "RundiNova Team"),):
            icon = frappe.get_doc("Desktop Icon", label)
            self.assertEqual(icon.link_to, label)
            self.assertTrue(icon.hidden)
            sidebar = frappe.get_doc("Workspace Sidebar", workspace)
            first_link = next(row for row in sidebar.items if row.type == "Link")
            self.assertEqual(
                (first_link.link_type, first_link.link_to), ("Workspace", workspace)
            )
            self.assertEqual(
                frappe.get_value("Workspace", workspace, "title"), sidebar.title
            )

    def test_legacy_workspace_routes_redirect_to_canonical_ascii_routes(self):
        self.assertIn(
            "/assets/rundinova_tech/js/rundinova_route_aliases.js",
            frappe.get_hooks("app_include_js"),
        )
        for page, destination in (
            ("configuration-rundinova", "/desk/rundinova-setup"),
            ("rundinova-équipe", "/desk/rundinova-tech"),
            ("rundinova-equipe", "/desk/rundinova-tech"),
        ):
            self.assertTrue(frappe.db.exists("Page", page))
            script = (
                Path(__file__).resolve().parents[2]
                / "public/js/rundinova_route_aliases.js"
            ).read_text()
            self.assertIn(f'"{page}":', script)
            self.assertIn(destination, script)
            self.assertIn(page, frappe.get_hooks("page_js"))
            self.assertEqual(
                frappe.get_hooks("page_js")[page][0],
                "public/js/rundinova_route_aliases.js",
            )
        self.assertIn('frappe.router.on("change"', script)
        self.assertIn("frappe.get_route?.()", script)

    def test_developers_have_a_dedicated_non_destructive_workspace(self):
        workspace = frappe.get_doc("Workspace", "RundiNova Developer")
        roles = {row.role for row in workspace.roles}
        links = {(row.type, row.link_to) for row in workspace.shortcuts}
        self.assertEqual(roles, {"RundiNova Developer"})
        self.assertTrue(
            {
                ("DocType", "Project"),
                ("DocType", "Task"),
                ("DocType", "RundiNova Repository"),
            }
            <= links
        )

        from rundinova_tech.rundinova_tech.access_control import (
            get_standard_doctype_permissions,
        )

        task_access = get_standard_doctype_permissions()[
            ("Task", "RundiNova Developer")
        ]
        project_access = get_standard_doctype_permissions()[
            ("Project", "RundiNova Developer")
        ]
        self.assertEqual(task_access["write"], 1)
        self.assertEqual(task_access["delete"], 0)
        self.assertEqual(project_access["write"], 0)

