    def test_crm_entry_role_is_granted_to_roles_that_use_crm(self):
        from rundinova_tech.rundinova_tech.provisioning import permissions

        roles_by_user = {
            "director@example.test": {"RundiNova Director"},
            "communications@example.test": {"RundiNova Communications"},
            "ecosystem@example.test": {"RundiNova Ecosystem Lead"},
            "growth@example.test": {"RundiNova Growth Lead"},
            "member@example.test": {"RundiNova Team Member"},
            "existing-sales@example.test": {"RundiNova Director", "Sales User"},
        }
        user_docs = {user: MagicMock() for user in roles_by_user}

        with (
            patch.object(frappe.db, "exists", return_value=True),
            patch.object(
                frappe, "get_all", return_value=list(roles_by_user)
            ) as get_users,
            patch.object(
                frappe,
                "get_roles",
                side_effect=lambda user: roles_by_user[user],
            ),
            patch.object(
                frappe,
                "get_doc",
                side_effect=lambda doctype, user: user_docs[user],
            ),
        ):
            updated = permissions.ensure_crm_app_access_roles()

        self.assertEqual(
            updated,
            [
                "director@example.test",
                "communications@example.test",
                "ecosystem@example.test",
                "growth@example.test",
            ],
        )
        get_users.assert_called_once_with(
            "User", filters={"user_type": "System User"}, pluck="name"
        )
        for user in updated:
            user_docs[user].append.assert_called_once_with(
                "roles", {"role": "Sales User"}
            )
            user_docs[user].save.assert_called_once_with(ignore_permissions=True)
        user_docs["member@example.test"].append.assert_not_called()
        user_docs["existing-sales@example.test"].append.assert_not_called()

