    def test_aggregated_dashboard_charts_use_category_grouping(self):
        for name, group_by, aggregate, value_field in (
            ("Budget consommé par aliment (%)", "item", "Average", "consumed_percent"),
            ("Solde par compte", "account_name", "Sum", "current_balance"),
            (
                "Budget consommé par période (%)",
                "budget_title",
                "Average",
                "consumed_percent",
            ),
            ("Valeur du pipeline par étape (FBu)", "stage", "Sum", "expected_value"),
        ):
            chart_name = frappe.get_value(
                "Dashboard Chart", {"chart_name": name}, "name"
            )
            self.assertTrue(chart_name, name)
            chart = frappe.get_doc("Dashboard Chart", chart_name)
            self.assertEqual(chart.chart_type, "Group By", name)
            self.assertEqual(chart.group_by_based_on, group_by, name)
            self.assertEqual(chart.group_by_type, aggregate, name)
            self.assertEqual(chart.value_based_on, value_field, name)
            self.assertFalse(chart.based_on, name)

    def test_monetary_dashboard_metrics_use_burundian_francs(self):
        for doctype, filters in (
            ("Number Card", {"label": "Solde de trésorerie"}),
            ("Number Card", {"label": "Budget planifié"}),
            ("Number Card", {"label": "Valeur du pipeline (FBu)"}),
            ("Dashboard Chart", {"chart_name": "Mouvements de trésorerie"}),
        ):
            self.assertEqual(
                frappe.get_value(doctype, filters, "currency"), "BIF", filters
            )
